349	        /// Sets the message's flags, `flags`, as `llhttp__after_message_complete` clears
350	        /// them.
351	        ///
352	        /// Wraps `fld::llhttp__internal_s.flags`
353	        #[doc(alias = "llhttp__internal_s.flags")]
354	        pub fn set_flags_raw(&mut self, flags: u16) {
355	            set!(self, flags, flags);
356	        }
357	    }
358	
359	    thread_local! {
360	        /// The addresses of the parsers this thread is inside `llhttp__internal_execute` for,
361	        /// innermost last: their callbacks, which run on the parsing thread, may parse other
362	        /// parsers, but neither parse nor initialise one of these.
363	        static EXECUTING: RefCell<Vec<usize>> = const { RefCell::new(Vec::new()) };
364	    }
365	
366	    /// A parser this thread is executing, registered for as long as the value lives.
367	    struct Executing(usize);
368	
369	    impl Executing {
370	        /// Registers the parser at `addr` as executing on this thread.
371	        ///
372	        /// # Panics
373	        ///
374	        /// When it is already: a callback of its own parse is parsing it again.
375	        fn enter(addr: usize) -> Self {
376	            EXECUTING.with_borrow_mut(|executing| {
377	                assert!(
378	                    !executing.contains(&addr),
379	                    "a callback parsed the llhttp parser whose parse runs it"
380	                );
381	                executing.push(addr);
382	            });
383	            Self(addr)
384	        }
385	
386	        /// Refuses to change the state of the parser at `addr` under its own parse.
387	        ///
388	        /// # Panics
389	        ///
390	        /// When the parser is executing on this thread: a callback of its parse is
391	        /// initialising it.
392	        fn refuse(addr: usize) {
393	            EXECUTING.with_borrow(|executing| {
394	                assert!(
395	                    !executing.contains(&addr),
396	                    "a callback initialised the llhttp parser whose parse runs it"
397	                );
398	            });
399	        }
400	    }
401	
402	    impl Drop for Executing {
403	        fn drop(&mut self) {
404	            // Registrations nest as the parses that make them do, so this one is the last.
405	            let last = EXECUTING.with_borrow_mut(Vec::pop);
406	            debug_assert_eq!(last, Some(self.0), "llhttp parses registered out of order");
407	        }
408	    }
409	
410	    impl Parser {
411	        /// A parser ready to read its first message: all-zero but for the start state, as
412	        /// `llhttp__internal_init` leaves it. It reads requests or responses, whichever comes
413	        /// first ([`ParserType::Both`]), has no error, no reason and no lenient flags, and its
414	        /// `data` and `settings` are NULL, so that a parse runs no callback.
415	        ///
416	        /// ```
417	        /// use libgit2_crustify::libgit2::deps::llhttp::llhttp::{Errno, Parsed, Parser, ParserType};
418	        ///
419	        /// let mut parser = Parser::new();
420	        /// assert_eq!(parser.as_ref().parser_type(), Ok(ParserType::Both));
421	        /// assert_eq!(parser.as_ref().error(), Ok(Errno::Ok));
422	        /// let response = b"HTTP/1.1 204 No Content\r\n\r\n";
423	        /// assert_eq!(parser.as_mut().parse(response), Ok(Parsed::All));
424	        /// assert_eq!(parser.as_ref().status_code(), 204);
425	        /// ```
426	        ///
427	        /// Wraps `fn::llhttp__internal_init`
428	        #[doc(alias = "llhttp__internal_init")]
429	        #[must_use]
430	        pub fn new() -> Self {
431	            let mut parser = <Self as CZeroable>::zeroed();
432	            init(parser.as_mut().as_mut_ptr());
433	            parser
434	        }
435	    }
436	
437	    impl Default for Parser {
438	        /// [`Parser::new`].
439	        fn default() -> Self {
440	            Self::new()
441	        }
442	    }
443	
444	    /// Runs `llhttp__internal_init` on the parser `parser` addresses.
445	    fn init(parser: *mut sys::llhttp__internal_t) {
446	        // SAFETY: `parser` comes from an exclusive handle, so it addresses a live
447	        // `llhttp__internal_s` nothing else accesses for the call. `llhttp__internal_init`
448	        // only `memset`s it and writes its start state into `_current`, keeping no pointer;
449	        // it returns 0 on its one path, so its result reports nothing.
450	        unsafe { sys::llhttp__internal_init(parser) };
451	    }
452	
453	    impl ParserMut<'_> {
454	        /// Initialises the parser again, in place, as [`Parser::new`] builds one: every
455	        /// field zero but the start state, its type, error, reason, flags, `data` and
456	        /// `settings` included. `llhttp_init` and `llhttp_reset` start so, and set back the
457	        /// fields they keep.
458	        ///
459	        /// # Panics
460	        ///
461	        /// When a callback of the parser's own [`parse`](Self::parse) calls it, which would
462	        /// leave the outer parse resuming from a state it did not leave.
463	        ///
464	        /// Wraps `fn::llhttp__internal_init`
465	        #[doc(alias = "llhttp__internal_init")]
466	        pub fn reinit(&mut self) {
467	            let parser = self.as_mut_ptr();
468	            Executing::refuse(parser.addr());
469	            init(parser);
470	        }
471	
472	        /// Parses `data`, a run of the input, calling the callbacks of the parser's settings
473	        /// as it reads each part of a message: llhttp's generated parser.
474	        ///
475	        /// The parser picks up where the previous run stopped, so a message may arrive in
476	        /// any number of runs. It keeps no pointer into `data` that it follows after the
477	        /// call: a span the run leaves open is passed to its callback before the call
478	        /// returns, and its error position is only compared with an input, never followed
479	        /// ([`ParserRef::error_offset`]).
480	        ///
481	        /// ```
482	        /// use libgit2_crustify::libgit2::deps::llhttp::llhttp::{Errno, Parsed, Parser};
483	        ///
484	        /// let mut parser = Parser::new();
485	        /// assert_eq!(
486	        ///     parser.as_mut().parse(b"HTTP/1.1 200 OK\r\nContent-"),
487	        ///     Ok(Parsed::All)
488	        /// );
489	        /// assert_eq!(
490	        ///     parser.as_mut().parse(b"Length: 2\r\n\r\nhi"),
491	        ///     Ok(Parsed::All)
492	        /// );
493	        /// assert_eq!(parser.as_ref().status_code(), 200);
494	        ///
495	        /// let error = parser.as_mut().parse(b"garbage").unwrap_err();
496	        /// assert_eq!(error.errno(), Ok(Errno::InvalidConstant));
497	        /// // The error is kept until the parser is initialised again.
498	        /// assert_eq!(parser.as_mut().parse(b"HTTP/1.1 200 OK\r\n"), Err(error));
499	        /// parser.as_mut().reinit();
500	        /// assert_eq!(
501	        ///     parser.as_mut().parse(b"HTTP/1.1 200 OK\r\n"),
502	        ///     Ok(Parsed::All)
503	        /// );
504	        /// ```
505	        ///
506	        /// # Errors
507	        ///
508	        /// The [`ParseError`] the parser stopped at, which it keeps: every later parse
509	        /// returns it again without reading, until the parser is initialised again.
510	        ///
511	        /// # Panics
512	        ///
513	        /// When the parser cannot run, where C would abort: it was never initialised, as
514	        /// [`CZeroable::zeroed`] builds it, or its error was cleared after one that leaves
515	        /// it nothing to resume from, such as `HPE_PAUSED_H2_UPGRADE`. And when a callback
516	        /// of the parser's own parse parses it again, which would corrupt the state the
517	        /// outer parse resumes from.
518	        ///
519	        /// Wraps `fn::llhttp__internal_execute`
520	        #[doc(alias = "llhttp__internal_execute")]
521	        pub fn parse(&mut self, data: &[u8]) -> Result<Parsed, ParseError> {
522	            let parser = self.as_mut_ptr();
523	            let _executing = Executing::enter(parser.addr());
524	            let runnable = {
525	                let this = self.as_ref();
526	                this.error_raw() != 0 || !get!(this, _current).is_null()
527	            };
528	            assert!(
529	                runnable,
530	                "the llhttp parser has no state to run from: it was never initialised, \
531	                 or was cleared of an error it cannot resume from"
532	            );
533	            let range = data.as_ptr_range();
534	            // SAFETY: `parser` comes from this exclusive handle, a live parser nothing else
535	            // accesses while the call runs but the callbacks C hands it to. Its private state
536	            // is C's own, from `llhttp__internal_init` or an earlier run: no accessor writes
537	            // `_current`, `_index` or the span fields. It is either in error, which the call
538	            // returns without running, or has a state to run from (checked above), so C's
539	            // `abort` on `s_error` is not reached. `range` bounds `data`, which is live and
540	            // unchanged for the call; C reads only within it, keeps `_span_pos0` and
541	            // `error_pos` pointing into it, and never follows either after the call: the
542	            // next run restarts an open span at its own input, and `error_pos` is never
543	            // followed by Rust. The settings' callbacks are NULL, or sound to call with this
544	            // parser and its `data` (`set_settings_ptr`'s and `set_data`'s contracts), and
545	            // none of them parses or initialises the parser again from Rust (`Executing`).
546	            let code = unsafe {
547	                sys::llhttp__internal_execute(parser, range.start.cast(), range.end.cast())
548	            };
549	            ParseError::outcome(code)
550	        }
551	    }
552	
553	    /// `llhttp_cb`'s function type: what a [`Callback`] holds and `llhttp.h`'s settings
554	    /// slots point to.
555	    type CallbackFn = unsafe extern "C" fn(*mut sys::llhttp_t) -> c_int;
556	
557	    /// `llhttp_data_cb`'s function type: what a [`DataCallback`] holds and `llhttp.h`'s
558	    /// settings slots point to.
559	    type DataCallbackFn = unsafe extern "C" fn(*mut sys::llhttp_t, *const c_char, usize) -> c_int;
560	
561	    /// An event callback (`llhttp_cb`): the C function a parser's settings name for an
562	    /// event of a message, such as its start or the end of its headers, which C calls with
563	    /// the parser being parsed.
564	    ///
565	    /// Built over an [`EventHandler`] with [`new`](Self::new), whose `extern "C"`
566	    /// trampoline hands the handler the parser's exclusive handle and catches its panics,
567	    /// or, inside the crate, over a C function, which its `unsafe` constructor vouches is
568	    /// sound to call with any parser. Either way [`call`](Self::call) is safe. A function
569	    /// pointer and nothing else: `Copy`, owning nothing, never released, and callable from
570	    /// any thread.
571	    ///
572	    /// ```
573	    /// use std::ffi::c_int;
574	    ///
575	    /// use libgit2_crustify::libgit2::deps::llhttp::llhttp::{
576	    ///     Callback, EventHandler, Parser, ParserMut,
577	    /// };
578	    ///
579	    /// struct Upgrading;
580	    ///
581	    /// impl EventHandler for Upgrading {
582	    ///     fn on_event(mut parser: ParserMut<'_>) -> c_int {
583	    ///         parser.set_upgrade(true);
584	    ///         0
585	    ///     }
586	    /// }
587	    ///
588	    /// const CALLBACK: Callback = Callback::new::<Upgrading>();
589	    /// let mut parser = Parser::new();
590	    /// assert_eq!(CALLBACK.call(parser.as_mut()), 0);
591	    /// assert!(parser.as_ref().upgrade());
592	    /// assert!(CALLBACK.raw().is_some());
593	    /// ```
594	    ///
595	    /// Its function is private: only `new` builds one outside the crate.
596	    ///
597	    /// ```compile_fail,E0423
598	    /// use libgit2_crustify::libgit2::deps::llhttp::llhttp::Callback;
599	    /// use libgit2_crustify::sys::libgit2 as sys;
600	    ///
601	    /// unsafe extern "C" fn c_callback(_: *mut sys::llhttp_t) -> std::ffi::c_int {
602	    ///     0
603	    /// }
604	    /// let _ = Callback(c_callback);
605	    /// ```
606	    ///
607	    /// Wraps `fnp::llhttp_cb`
608	    #[doc(alias = "llhttp_cb")]
609	    #[derive(Clone, Copy)]
610	    pub struct Callback(CallbackFn);
611	
612	    impl Callback {
613	        /// The callback that hands C's calls to `H`.
614	        #[must_use]
615	        pub const fn new<H: EventHandler>() -> Self {
616	            Self(event_with::<H>)
617	        }
618	
619	        /// The callback over a C function.
620	        ///
621	        /// # Safety
622	        ///
623	        /// For as long as this value or a copy of it lives, `f` must be sound to call with
624	        /// every live, exclusively held parser, in any state and whatever its `data` and
625	        /// `settings` hold, on the thread that holds the parser, and must not unwind: those
626	        /// are the calls [`call`](Self::call) makes, and those of the parsers a
627	        /// [`Settings`](crate::libgit2::deps::llhttp::api::Settings) holding it is given. Where
628	        /// it sets the parser's `reason`, it sets it NULL or to a NUL-terminated string that
629	        /// lives, unchanged, as long as the program, since it may serve any parser, which
630	        /// [`ParserRef::reason`] reads at any time. A C
631	        /// callback that reads the parser's `data` as its own context does not meet this,
632	        /// and is reached through the settings its parser executes with instead, stored by
633	        /// [`ParserMut::set_settings_ptr`], whose contract vouches for it.
634	        pub(crate) const unsafe fn from_fn(f: CallbackFn) -> Self {
635	            Self(f)
636	        }
637	
638	        /// Calls the callback with `parser`, as llhttp does, and returns what it returns.
639	        #[must_use = "the callback's return tells the parse how to go on"]
640	        pub fn call(self, mut parser: ParserMut<'_>) -> c_int {
641	            // SAFETY: `parser` addresses a live parser this exclusive handle lends for the
642	            // call: `CallbackFn`'s only argument. `new`'s trampolines need nothing more, and
643	            // `from_fn`'s caller vouched that the function is sound with any such parser.
644	            unsafe { (self.0)(parser.as_mut_ptr()) }
645	        }
646	
647	        /// The C value, as a settings slot holds it: never NULL.
648	        #[must_use]
649	        pub const fn raw(self) -> sys::llhttp_cb {
650	            Some(self.0)
651	        }
652	    }
653	
654	    impl fmt::Debug for Callback {
655	        fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
656	            f.debug_tuple("Callback")
657	                .field(&(self.0 as *const ()))
658	                .finish()
659	        }
660	    }
661	
662	    /// `llhttp_cb` over [`EventHandler::on_event`].
663	    ///
664	    /// # Safety
665	    ///
666	    /// `parser` is NULL or addresses a live parser nothing else accesses for the call but
667	    /// the handles this call makes: llhttp's call with the parser it is parsing, and
668	    /// [`Callback::call`]'s.
669	    unsafe extern "C" fn event_with<H: EventHandler>(parser: *mut sys::llhttp_t) -> c_int {
670	        // SAFETY: per this function's contract, a non-NULL `parser` is a live parser lent
671	        // to the call alone; the handle's borrow ends with the call.
672	        let Some(parser) = (unsafe { ParserMut::from_ptr(parser) }) else {
673	            return -1;
674	        };
675	        callback::barrier(|| H::on_event(parser), || -1)
676	    }
677	
678	    /// A data callback (`llhttp_data_cb`): the C function a parser's settings name for a
679	    /// run of the input that makes up a part of a message, such as its URL, a header's
680	    /// name or value, or its body, which C calls with the parser and the run.
681	    ///
682	    /// Built over a [`DataHandler`] with [`new`](Self::new), whose trampoline hands the
683	    /// handler the parser's handle and the run as a slice borrowed for the call, or, inside
684	    /// the crate, over a C function, as [`Callback`] is. A part may come in several runs,
685	    /// one per call, when it spans several parses. A function pointer and nothing else.
686	    ///
687	    /// ```
688	    /// use std::cell::RefCell;
689	    /// use std::ffi::c_int;
690	    ///
691	    /// use libgit2_crustify::libgit2::deps::llhttp::llhttp::{DataCallback, DataHandler, Parser, ParserMut};
692	    ///
693	    /// thread_local!(static SEEN: RefCell<Vec<u8>> = const { RefCell::new(Vec::new()) });
694	    ///
695	    /// struct Collect;
696	    ///
697	    /// impl DataHandler for Collect {
698	    ///     fn on_data(_: ParserMut<'_>, data: &[u8]) -> c_int {
699	    ///         SEEN.with_borrow_mut(|seen| seen.extend_from_slice(data));
700	    ///         0
701	    ///     }
702	    /// }
703	    ///
704	    /// const CALLBACK: DataCallback = DataCallback::new::<Collect>();
705	    /// let mut parser = Parser::new();
706	    /// assert_eq!(CALLBACK.call(parser.as_mut(), b"Host"), 0);
707	    /// assert_eq!(SEEN.with_borrow(Vec::clone), b"Host");
708	    /// ```
709	    ///
710	    /// Wraps `fnp::llhttp_data_cb`
711	    #[doc(alias = "llhttp_data_cb")]
712	    #[derive(Clone, Copy)]
713	    pub struct DataCallback(DataCallbackFn);
714	
715	    impl DataCallback {
716	        /// The callback that hands C's calls to `H`.
717	        #[must_use]
718	        pub const fn new<H: DataHandler>() -> Self {
719	            Self(data_with::<H>)
720	        }
721	
722	        /// The callback over a C function.
723	        ///
724	        /// # Safety
725	        ///
726	        /// As [`Callback::from_fn`]'s, the calls being [`call`](Self::call)'s: with every
727	        /// live, exclusively held parser, and a run of bytes live and unchanged for the
728	        /// call, its start and its length.
729	        pub(crate) const unsafe fn from_fn(f: DataCallbackFn) -> Self {
730	            Self(f)
731	        }
732	
733	        /// Calls the callback with `parser` and `data`, as llhttp does, and returns what it
734	        /// returns.
735	        #[must_use = "the callback's return tells the parse how to go on"]
736	        pub fn call(self, mut parser: ParserMut<'_>, data: &[u8]) -> c_int {
737	            // SAFETY: `parser` addresses a live parser this exclusive handle lends for the
738	            // call, and `data` a run of `data.len()` bytes live and unchanged for it:
739	            // `DataCallbackFn`'s arguments. `new`'s trampolines need nothing more, and
740	            // `from_fn`'s caller vouched for the function with any such arguments.
741	            unsafe { (self.0)(parser.as_mut_ptr(), data.as_ptr().cast(), data.len()) }
742	        }
743	
744	        /// The C value, as a settings slot holds it: never NULL.
745	        #[must_use]
746	        pub const fn raw(self) -> sys::llhttp_data_cb {
747	            Some(self.0)
748	        }
749	    }
750	
751	    impl fmt::Debug for DataCallback {
752	        fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
753	            f.debug_tuple("DataCallback")
754	                .field(&(self.0 as *const ()))
755	                .finish()
756	        }
757	    }
758	
759	    /// `llhttp_data_cb` over [`DataHandler::on_data`].
760	    ///
761	    /// # Safety
762	    ///
763	    /// As [`event_with`]'s for `parser`; and `at` is NULL or addresses `length` bytes live
764	    /// and unchanged for the call: llhttp's span, from its start to where it read, within
765	    /// the input of the parse, or [`DataCallback::call`]'s slice.
766	    unsafe extern "C" fn data_with<H: DataHandler>(
767	        parser: *mut sys::llhttp_t,
768	        at: *const c_char,
769	        length: usize,
770	    ) -> c_int {
771	        // SAFETY: per this function's contract, a non-NULL `parser` is a live parser lent
772	        // to the call alone; the handle's borrow ends with the call.
773	        let Some(parser) = (unsafe { ParserMut::from_ptr(parser) }) else {
774	            return -1;
775	        };
776	        let data: &[u8] = if length == 0 {
777	            &[]
778	        } else if at.is_null() {
779	            return -1;
780	        } else {
781	            // SAFETY: per this function's contract, a non-NULL `at` addresses `length`
782	            // initialised bytes, which nothing writes or frees for the call, the slice's
783	            // borrow; `u8` is aligned to 1.
784	            unsafe { core::slice::from_raw_parts(at.cast::<u8>(), length) }
785	        };
786	        callback::barrier(|| H::on_data(parser, data), || -1)
787	    }
788	}
