/// destructor that settles one owned `*mut T` — a `*_free` or a down-ref.
///
/// ```ignore
/// #[derive(Clone, Copy, Debug, Default)]
/// pub struct FooFree;
/// impl_cdrop!(FooFree, Foo, ffi::foo_free);
